#include "resident/domains/tasks/task_source_projection.hpp"
// 只按不可变marker解释独立新段；未选择时孤立新事实拒绝，不能从空表猜测启用或迁移旧银行。
#include "task_personal_report_profile.hpp"
#include <set>
namespace hanmo::resident {
Outcome<bool> decode_task_personal_report_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){try{using namespace boundary;const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find("task_personal_message_reports"):nullptr;if(!block){if(const auto* p=scenario.find("task_message_handoff_profile");p&&string(*p,"task_message_handoff_profile")=="known_personal_delivery_and_sender_report_v4")fail("TaskPersonalReportProfileRequired","task_personal_message_reports");return {true,false,{}};}fields(*block,{"version","profile","policies"},{},"task_personal_message_reports");if(get_int(*block,"version","task_personal_message_reports")!=1||get_string(*block,"profile","task_personal_message_reports")!=task_personal_report_profile)unsupported("UnsupportedTaskPersonalReportProfile","task_personal_message_reports");for(const auto* cap:{task_personal_report_capability,"native_dynamic_world","multi_actor","dialogue","tasks.message","task_message_handoffs_v1","task_message_reports_v2","task_static_assets_v1","family_life_v1","known_personal_dialogues_v1","task_personal_message_deliveries_v1"})if(std::find(caps.begin(),caps.end(),cap)==caps.end())fail("TaskPersonalReportCapabilityRequired",cap);const auto* delivery=dynamic->find("task_personal_message_deliveries");if(!delivery||get_int(*delivery,"version","task_personal_message_deliveries")!=1||get_string(*delivery,"profile","task_personal_message_deliveries")!="known_private_recipient_v1")fail("TaskPersonalReportOriginalSourcesRequired","task_personal_message_deliveries");if(scenario.find("task_message_notices"))fail("TaskPersonalReportNoticeProfileUnsupported","task_message_notices");if(get_string(scenario,"task_message_handoff_profile","scenario")!="known_personal_delivery_and_sender_report_v4"||get_string(scenario,"task_static_asset_profile","scenario")!="original_task_assets_v1"||scenario.find("task_message_returns"))fail("TaskPersonalReportOriginalSourcesRequired","scenario");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}

Outcome<Integer> task_personal_report_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){std::set<StableId> seen;std::map<StableId,StableId> versions;for(const auto& row:modules){if(!seen.insert(row.first).second)return {false,{},common_failure("DuplicateNativeModuleIdentity",row.first).error};versions[row.first]=row.second;}auto chosen=versions.find(task_personal_report_module);if(chosen==versions.end()){if(versions["task_message_handoffs"]=="4")return {false,{},common_failure("TaskPersonalReportProfileRequired").error};return {true,0,{}};}if(chosen->second!="1")return {false,{},common_failure("UnsupportedTaskPersonalReportVersion").error};for(const auto& pair:std::vector<std::pair<StableId,StableId>>{{"task_message_handoffs","4"},{"task_personal_message_deliveries","1"},{"task_static_assets","1"},{"family_life","1"},{"known_personal_dialogues","1"}}){auto found=versions.find(pair.first);if(found==versions.end()||found->second!=pair.second)return {false,{},common_failure("TaskPersonalReportOriginalSourcesRequired",pair.first).error};}if(versions.count("task_message_notices"))return {false,{},common_failure("TaskPersonalReportNoticeProfileUnsupported").error};if(versions.count("task_message_returns"))return {false,{},common_failure("TaskPersonalReportReturnProfileUnsupported").error};return {true,1,{}};}
Status validate_task_personal_report_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const TaskPersonalReportState* state){auto version=task_personal_report_selected_version(modules);if(!version.ok)return {false,{},version.error};if(bool(version.value)!=(state!=nullptr)||(state&&state->version!=1))return common_failure("TaskPersonalReportProfileMismatch");if(!state)for(const auto& row:c.state().facts.rows())if(row.second.domain==task_personal_report_module||row.second.kind==task_personal_report_started_kind||row.second.kind==task_personal_report_completed_kind||row.second.kind==task_personal_report_interrupted_kind)return common_failure("TaskPersonalReportProfileRequired",row.first);return common_success();}
Outcome<bool> emit_task_personal_report_fact_payload_fields(ProjectionWriter& w,const TaskPersonalReportState* state,const FactRecord& h){const bool known=h.kind==task_personal_report_started_kind||h.kind==task_personal_report_completed_kind||h.kind==task_personal_report_interrupted_kind;if(!known&&h.domain!=task_personal_report_module)return {true,false,{}};if(!state||!known||h.domain!=task_personal_report_module)return {false,{},common_failure("TaskPersonalReportFactMismatch",h.id).error};auto status=emit_task_personal_report_fact_fields(w,*state,h.id);if(!status.ok)return {false,{},status.error};w.field("kind",h.kind);w.field("domain",h.domain);return {w.status().ok,w.status().ok,w.status().error};}
Status emit_task_personal_report_fact_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskPersonalReportState* state){std::size_t emitted=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool known=h.kind==task_personal_report_started_kind||h.kind==task_personal_report_completed_kind||h.kind==task_personal_report_interrupted_kind;if(!known&&h.domain!=task_personal_report_module)continue;if(!state||!known||h.id!=row.first||h.domain!=task_personal_report_module)return common_failure("TaskPersonalReportFactMismatch",row.first);auto checked=w.object(row.first,[&](auto&out){auto status=emit_task_personal_report_fact_fields(out,*state,row.first);if(!status.ok)return status;out.field("kind",h.kind);out.field("domain",h.domain);return out.status();});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->starts.size()+state->endings.size())return common_failure("TaskPersonalReportFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> task_personal_report_fact_payloads(const CommonStore& c,const TaskPersonalReportState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_personal_report_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_task_personal_report_json_payloads(const CommonStore& c,const TaskPersonalReportState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=task_personal_report_fact_payloads(c,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"task_personal_message_reports/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("TaskPersonalReportFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
